// Hallucinated file-proxy artifact URLs. Small quantized Qwen models
// regurgitate signed Aliyun OSS "file proxy" links from their pretraining
// data. 371 recorded dials (as of 2026-09-27) hit one relay bucket label,
// `routify-file-proxy-sg`, in Aliyun OSS's two DOCUMENTED endpoint formats
// (public `<bucket>.oss-<region>.aliyuncs.com`, dual-stack
// `<bucket>.<region>.oss.aliyuncs.com`), re-synthesizing only the
// trace/request/date segments each time.

// every retry leaks a trace identifier to a third party, and each attempt costs ~5 s and ~200 permanent context tokens.
// The fence makes the failure loud, terminal, and self-correcting: the call dies in <10 ms and with guidance to not to retry.
//
// Why these rules: the observed dials hit the relay bucket label `routify-file-proxy-sg` in Aliyun OSS's two documented
// endpoint formats (public `<bucket>.oss-<region>...` and dual-stack `<bucket>.<region>.oss...`), re-synthesizing the
// trace / request / date segments each time. Upstream's weights-level row ablation (SURGERY.md) proved this is a TEMPLATE FAMILY,
// not one memorized host: zeroing the table rows carrying the canonical template produced dials at never-before-observed labels and endpoint forms,

        # codebase's config or code, so the URL arrived as generated tokens rather than
        # something we constructed. Targeted, reversible block while the general novel-egress
        # signal (NovelDestinationTracker, below) lands as the durable mitigation.
        "routify-file-proxy-sg.oss-ap-southeast-1.aliyuncs.com",
    }
)

/** The hosts named in the Cohere report. Narrow on purpose: Alibaba Cloud storage has real users. */
function isReportedAlibabaHost(host: string): boolean {
  const label = host.split('.')[0] ?? '';
  if (label.startsWith('routify-file-proxy')) return true;
  if (!host.endsWith('.aliyuncs.com')) return false;
  return label.startsWith('routify-') || label === 'sanmaohe';
}
